import json,sys
try:
    d=json.load(open('$f'))
except Exception as e:
    print('parse error',e); sys.exit()
def walk(o,path=''):
    if isinstance(o,dict):
        for k,v in o.items():
            if k in ('yt-local','yt_local','yt'):
                print(path+'/'+k, '->', {kk:(vv if kk!='env' else {ek:'<set>' for ek in vv}) for kk,vv in v.items()} if isinstance(v,dict) else v)
            else:
                walk(v,path+'/'+k)
walk(d)
"; done

